  ('Hydrolyzed Corn Starch', 'MaízCare (biopolímero de maíz)', array['Formador de película', 'Matificante', 'Reafirmante']::text[], null, '1-3% (según la ficha del proveedor)', 'Biopolímero derivado del maíz que forma una película fina y flexible sobre la piel o el cabello. Da efecto tensor inmediato y visual mate o soft-focus; en cabello sella la cutícula y da brillo.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Espesantes y gelificantes', 'El efecto es de película: se va al lavar y no cambia la estructura de la piel', null, false),
  ('Maltodextrin', 'Maltodextrina', array['Agente de carga', 'Vehículo']::text[], null, 'Según el uso', 'Polisacárido de maíz o tapioca. Se usa como soporte de polvos y en microencapsulación.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Espesantes y gelificantes', null, null, false),
