  ('Luma Apiculata Leaf Water', 'Hidrolato de arrayán', array['Astringente', 'Tonificante']::text[], null, 'Hasta 100% de la fase acuosa', 'Agua aromática de hojas de arrayán, nativo del sur de Chile y Argentina.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Hidrolatos y aguas', 'Refrigerar y conservar', null, false),
  ('Drimys Winteri Leaf Water', 'Hidrolato de canelo', array['Tonificante', 'Antimicrobiano']::text[], null, 'Hasta 100% de la fase acuosa', 'Agua aromática de hojas de canelo (foye), el árbol sagrado mapuche.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Hidrolatos y aguas', 'Refrigerar y conservar', null, false),
  ('Cocos Nucifera Fruit Juice', 'Agua de coco', array['Humectante']::text[], null, 'Hasta 100% de la fase acuosa', 'Líquido del interior del coco, con azúcares y minerales. Se usa como base hidratante suave.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Hidrolatos y aguas', 'Se contamina rápidamente: conservar', null, false),
  ('Maris Aqua', 'Agua de mar', array['Mineral', 'Tonificante']::text[], null, 'Hasta 100% de la fase acuosa', 'Agua de mar filtrada o isotónica. Se usa en sprays corporales y capilares por su aporte mineral.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Hidrolatos y aguas', 'Puede resecar si se usa pura', null, false),
  ('Glycerin', 'Glicerina vegetal', array['Humectante', 'Disolvente']::text[], null, '2-10% (hasta 20% en ciertos productos)', 'El humectante universal: atrae agua hacia la piel. Subproducto de la saponificación, es barata y estable.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', 'Sobre ~10% puede sentirse pegajosa. En ambientes muy secos conviene combinarla con un oclusivo', null, false),
  ('Propanediol', 'Propanodiol', array['Humectante', 'Disolvente', 'Potenciador de conservante']::text[], null, '1-10%', 'Humectante y solvente de origen vegetal (de maíz). Mejora la sensación en piel y potencia la acción de los conservantes.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', null, null, false),
  ('Butylene Glycol', 'Butilenglicol', array['Humectante', 'Disolvente']::text[], null, '1-10%', 'Humectante y solvente ligero, muy usado en sérums. Tacto no pegajoso.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', 'No es de origen natural, salvo la versión bio', null, false),
  ('Propylene Glycol', 'Propilenglicol', array['Humectante', 'Disolvente']::text[], null, '1-10%', 'Humectante y solvente clásico, de eficacia comprobada.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', 'Puede irritar o sensibilizar en piel sensible; no es natural', null, false),
  ('Pentylene Glycol', 'Pentilenglicol', array['Humectante', 'Potenciador de conservante']::text[], null, '1-5%', 'Humectante que también aumenta la eficacia de los conservantes. Existe de origen vegetal.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', null, null, false),
  ('Sorbitol', 'Sorbitol', array['Humectante']::text[], null, '2-10%', 'Humectante de origen vegetal, algo más ligero que la glicerina.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', null, null, false),
  ('Xylitol', 'Xilitol', array['Humectante', 'Antimicrobiano']::text[], null, '1-5%', 'Alcohol de azúcar que humecta la piel y deja sensación fresca. Se usa como humectante de apoyo junto a la glicerina.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', null, null, false),
  ('Erythritol', 'Eritritol', array['Humectante', 'Refrescante']::text[], null, '1-5%', 'Alcohol de azúcar que humecta y da sensación fresca al disolverse.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', null, null, false),
  ('Trehalose', 'Trehalosa', array['Humectante', 'Protector']::text[], null, '1-5%', 'Azúcar que protege las células de la deshidratación y del estrés. Se usa en sérums hidratantes.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', null, null, false),
  ('Sodium PCA', 'PCA sódico', array['Humectante']::text[], null, '0.5-5%', 'Parte del factor natural de humectación (NMF) de la piel. Humectante muy eficaz y de buen tacto.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', null, null, false),
  ('Urea', 'Urea', array['Humectante', 'Queratolítico']::text[], null, '2-5% hidratante; 10-40% queratolítico', 'Compuesto del factor natural de humectación. A baja dosis hidrata; a dosis altas (sobre ~10%) suaviza callosidades y exfolia.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', 'Concentraciones altas pueden arder en piel con heridas. En agua se descompone con calor y pH extremo', null, false),
  ('Hydroxyethyl Urea', 'Hidroxietil urea', array['Humectante']::text[], null, '2-10%', 'Humectante derivado de urea, más estable y de tacto menos pegajoso.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', null, null, false),
  ('Sodium Lactate', 'Lactato de sodio', array['Humectante', 'Regulador de pH']::text[], null, '1-5%', 'Sal del ácido láctico. Parte del NMF y, junto al ácido láctico, forma un tampón que estabiliza el pH.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', null, null, false),
  ('Betaine', 'Betaína', array['Humectante', 'Calmante']::text[], null, '1-5%', 'Obtenida de la remolacha. Humectante suave que además reduce la irritación que causan los tensioactivos.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', null, null, false),
  ('Sodium Hyaluronate', 'Ácido hialurónico (hialuronato de sodio)', array['Humectante', 'Acondicionador de piel']::text[], null, '0.1-2%', 'Polisacárido que retiene mucha agua. Según su peso molecular, actúa en superficie (alto) o penetra más (bajo).', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', 'Dispersar en agua o glicerina para evitar grumos', null, false),
  ('Hyaluronic Acid', 'Ácido hialurónico (forma ácida)', array['Humectante']::text[], null, '0.1-2%', 'Forma ácida del hialurónico, menos usada que su sal.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', null, null, false),
  ('Panthenol', 'Pantenol (provitamina B5)', array['Humectante', 'Calmante', 'Regenerador']::text[], null, '0.5-5%', 'Se convierte en ácido pantoténico en la piel. Humectante, cicatrizante y calmante; excelente en pieles sensibles y para el cabello.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', 'La versión líquida al 75% pesa más: ajusta la dosis', null, false),
  ('Allantoin', 'Alantoína', array['Calmante', 'Cicatrizante', 'Queratolítico']::text[], null, '0.1-0.5%', 'Compuesto originalmente aislado de la consuelda. Queratolítico suave, calmante y favorecedor de la regeneración.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', 'Poco soluble en frío: disolver en agua caliente', null, false),
  ('Mel', 'Miel', array['Humectante', 'Antimicrobiano']::text[], null, '1-5%', 'Humectante natural por su alta concentración de azúcares. Aporta suavidad; en concentraciones muy altas es antimicrobiana.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', 'En fórmulas con agua necesita conservante. Puede dar alergia en personas sensibles a los productos de las abejas', null, false),
  ('Aloe Barbadensis Leaf Juice Powder', 'Aloe vera en polvo (200x)', array['Humectante', 'Calmante']::text[], null, '0.5-2% del polvo', 'Gel de aloe deshidratado y concentrado. Se reconstituye en agua para hacer gel.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', 'Reconstituir con conservante; el gel fresco se contamina rápido', null, false),
  ('Glucose', 'Glucosa', array['Humectante']::text[], null, '1-5%', 'Azúcar simple que humecta y que sirve de base a algunos limpiadores suaves.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', null, null, false),
  ('Polyglyceryl-6 Caprylate', 'Caprilato de poliglicerilo-6', array['Humectante', 'Emulsionante']::text[], null, '1-5%', 'Éster de poliglicerina de origen vegetal; humecta y mejora la tolerancia de otros tensioactivos.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', null, null, false),
  ('Algin', 'Ácido algínico', array['Humectante', 'Gelificante']::text[], null, '0.5-2%', 'Extraído de algas pardas. Forma geles con efecto humectante.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', null, null, false),
  ('Sodium Carboxymethyl Betaglucan', 'Betaglucano', array['Humectante', 'Calmante', 'Antioxidante']::text[], null, '0.1-1%', 'Polisacárido de avena o levadura. Hidrata, calma y mejora la elasticidad; muy usado en piel sensible.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Humectantes e hidratantes', null, null, false),
  ('Butyrospermum Parkii Butter', 'Manteca de karité', array['Emoliente', 'Estructurante', 'Nutritivo']::text[], null, '3-10% en cremas; 20-50% en bálsamos', 'Grasa sólida de las nueces del árbol africano del karité. Sus ácidos oleico y esteárico la hacen cremosa y nutritiva; su fracción insaponificable (triterpenos, tocoferoles, esteroles) aporta efecto calmante y antioxidante.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', 'Si se enfría lento puede granularse: enfría rápido o recalienta. La sin refinar huele ahumado', null, false),
  ('Theobroma Cacao Seed Butter', 'Manteca de cacao', array['Emoliente', 'Estructurante', 'Oclusivo']::text[], null, '2-10% en cremas; 10-30% en bálsamos', 'Grasa dura y quebradiza, rica en ácidos esteárico, oleico y palmítico. Funde cerca de los 34 °C. Da dureza y brillo a bálsamos y labiales.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', 'En piel muy grasa puede sentirse pesada en el rostro', null, false),
  ('Mangifera Indica Seed Butter', 'Manteca de mango', array['Emoliente', 'Estructurante']::text[], null, '3-10% en cremas; 10-30% en bálsamos', 'Manteca suave y poco pegajosa, rica en ácidos esteárico y oleico. Más ligera que el karité, con muy buen deslizamiento.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Coffea Arabica Seed Butter', 'Manteca (aceite) de café verde', array['Emoliente', 'Antioxidante']::text[], null, '2-10%', 'Grasa de granos de café sin tostar, con ácidos linoleico y palmítico, esteroles y tocoferoles. Emoliente de tacto seco. Se le atribuye efecto tonificante; la evidencia clínica es limitada.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Garcinia Indica Seed Butter', 'Manteca de kokum', array['Emoliente', 'Estructurante']::text[], null, '3-20%', 'Manteca dura y poco grasosa, rica en ácidos esteárico y oleico. Muy estable; sirve en barras y bálsamos.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Shorea Robusta Seed Butter', 'Manteca de sal', array['Emoliente', 'Estructurante']::text[], null, '3-20%', 'Manteca firme, parecida a la de cacao y al karité, rica en ácido esteárico.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Theobroma Grandiflorum Seed Butter', 'Manteca de cupuaçu', array['Emoliente', 'Humectante']::text[], null, '3-10%', 'Manteca amazónica de buena capacidad de retener agua y de tacto suave.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Astrocaryum Murumuru Seed Butter', 'Manteca de murumuru', array['Emoliente', 'Estructurante']::text[], null, '3-10%', 'Manteca amazónica rica en ácido láurico y mirístico; algo dura y de tacto seco. Se usa en cabello y piel.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Tallow', 'Sebo bovino purificado (tallow)', array['Emoliente', 'Oclusivo', 'Estructurante']::text[], null, '10-100% según el producto', 'Grasa bovina purificada, con ácidos oleico (~45%), palmítico y esteárico; composición parecida a la barrera lipídica de la piel. Sólida a temperatura ambiente; funde a 40-45 °C. Base de ungüentos y bálsamos.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', 'Sin agua no necesita conservante; con agua sí. El de animales pasturados suele ser más rico en vitaminas liposolubles', null, false),
  ('Lanolin', 'Lanolina', array['Emoliente', 'Oclusivo']::text[], null, '2-10%', 'Grasa natural de la lana de oveja. Emoliente y oclusiva muy eficaz: retiene la humedad de la piel.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', 'No es vegana. Puede sensibilizar; usa grado cosmético purificado', null, false),
  ('Cera Alba', 'Cera de abeja', array['Estructurante', 'Emulsionante', 'Oclusivo']::text[], null, '2-10% en cremas; 10-25% en bálsamos', 'Cera de abejas blanqueada o natural. Da cuerpo y protege la piel con una película permeable; coemulsionante débil con bórax o cera emulsionante.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', 'No es vegana. Algunas personas reaccionan a los productos de las abejas', null, false),
  ('Euphorbia Cerifera Wax', 'Cera de candelilla', array['Estructurante', 'Formador de película']::text[], null, '50% de la cantidad de cera de abeja que reemplaza', 'Cera vegetal dura y brillante de un arbusto del desierto mexicano. Alternativa vegana a la cera de abeja.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', 'Punto de fusión 68-73 °C', null, false),
  ('Copernicia Cerifera Wax', 'Cera de carnauba', array['Estructurante', 'Brillo']::text[], null, '1-5% en barras y labiales', 'La cera vegetal más dura (fusión ~80-86 °C), de palmas de Brasil. Da dureza y brillo espejo.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', 'Sube mucho el punto de fusión de la mezcla', null, false),
  ('Helianthus Annuus Seed Wax', 'Cera de girasol', array['Estructurante']::text[], null, '1-8%', 'Cera vegetal ligera, usada como alternativa vegana a la de abeja.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Oryza Sativa Bran Wax', 'Cera de salvado de arroz', array['Estructurante']::text[], null, '1-8%', 'Cera vegetal de punto de fusión medio-alto. Usada en barras, labiales y bálsamos.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Hydrogenated Soybean Oil', 'Cera de soya', array['Estructurante']::text[], null, '5-20% en bálsamos', 'Aceite de soya hidrogenado, sólido y de textura cerosa. Da cuerpo a velas, bálsamos y cremas.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', 'Evitar si hay alergia a la soya', null, false),
  ('Stearic Acid', 'Ácido esteárico', array['Estructurante', 'Coemulsionante']::text[], null, '1-10%', 'Ácido graso saturado (C18) de origen vegetal. Da cuerpo y nacarado a las cremas y forma emulsiones con una base (por ejemplo, con trietanolamina o cera emulsionante).', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Palmitic Acid', 'Ácido palmítico', array['Estructurante']::text[], null, '1-5%', 'Ácido graso saturado (C16) de aceite de palma o coco. Se usa como espesante y estructurante.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', 'Revisa que el origen del aceite de palma sea sostenible', null, false),
  ('Cetyl Alcohol', 'Alcohol cetílico', array['Coemulsionante', 'Espesante', 'Emoliente']::text[], null, '2-6%', 'Alcohol graso sólido de origen vegetal (no es alcohol etílico): no reseca. Da cuerpo y tacto sedoso a cremas y acondicionadores.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Stearyl Alcohol', 'Alcohol estearílico', array['Coemulsionante', 'Espesante', 'Emoliente']::text[], null, '2-5%', 'Alcohol graso sólido, primo del cetílico pero más cerúleo. Da estructura y cuerpo a cremas y acondicionadores.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Cetearyl Alcohol', 'Alcohol cetearílico', array['Coemulsionante', 'Espesante']::text[], null, '3-8%', 'Mezcla de alcohol cetílico y estearílico. Coemulsionante y espesante de referencia en cremas y acondicionadores.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Behenyl Alcohol', 'Alcohol behenílico', array['Espesante', 'Estructurante']::text[], null, '1-5%', 'Alcohol graso de cadena larga (C22). Da cuerpo rico y un tacto aterciopelado; base de los acondicionadores.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Glyceryl Stearate', 'Monoestearato de glicerina (GMS)', array['Coemulsionante', 'Estructurante', 'Emoliente']::text[], null, '2-5%', 'Coemulsionante no iónico de origen vegetal. Refuerza la emulsión y da cuerpo y suavidad.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Glyceryl Oleate', 'Oleato de glicerilo', array['Emoliente', 'Coemulsionante']::text[], null, '1-5%', 'Emoliente y coemulsionante suave de origen vegetal.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Cetyl Palmitate', 'Palmitato de cetilo', array['Estructurante', 'Emoliente']::text[], null, '1-5%', 'Éster ceroso (parecido al espermaceti) de origen vegetal. Da cuerpo y suavidad a cremas y barras.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
  ('Cetyl Esters', 'Ésteres de cetilo', array['Estructurante', 'Emoliente']::text[], null, '1-5%', 'Mezcla de ésteres cerosos vegetales usados como sustituto del espermaceti.', 'floema', 'Referencia general de formulación; borrador por verificar con la ficha del proveedor y la biblioteca', 'Mantecas, ceras y emolientes', null, null, false),
